parameters.jsCode:
// KONTEXT: Quellenprüfung nach der KI. Jede Zusammenfassung darf nur Artikel nennen, die für ihr Feld erlaubt sind. Sonst wird sie durch einen Hinweis ersetzt. Fällt die KI aus, kommt das Ergebnis trotzdem, nur ohne Zusammenfassungen.
// BEISPIEL: Die Zusammenfassung zu "rolle|D" nennt DSGVO Art. 28 (erlaubt) und Art. 99 (nicht erlaubt), also wird sie ersetzt. kiStatus = partial.

// ---------- ABSCHNITT 1: Konstanten ----------
// „Dieser Hinweis ersetzt eine Zusammenfassung, die geprüft nicht standhält.“
const NOTE = 'Für diese Antwort liegt keine geprüfte Zusammenfassung vor. Die Artikel unten gelten trotzdem.';

// ---------- ABSCHNITT 2: Daten holen ----------
// „Die Regeln und Aufgaben stehen noch in der Regel-Node, die KI-Antwort kommt aus dem vorigen Schritt.“
const r = $('Rules').first().json;
// „Die Liste der Zusammenfassungen, falls die KI geantwortet hat.“
const list = $json.output?.summaries;
// „Hier landen die geprüften Zusammenfassungen und die ersetzten Schlüssel.“
const summaries = {}; const replaced = [];

// ---------- ABSCHNITT 3: Zusammenfassungen prüfen ----------
// „Hat die KI nichts Brauchbares geliefert, gibt es keine Zusammenfassungen und der Status heißt fallback.“
if (Array.isArray(list)) {
  // „Jede Aufgabe einzeln prüfen, auch wenn die KI sie vergessen hat.“
  for (const t of r.tasks) {
    // „Die Zusammenfassung der KI zu dieser Aufgabe suchen.“
    const s = list.find(x => x && x.key === t.key);
    // „Fehlt sie, bleibt der Schlüssel leer, die Seite zeigt dann nur die Artikel.“
    if (!s || typeof s.text !== 'string' || !s.text.trim()) continue;
    // „Alle genannten Artikelnummern aus dem Text holen (Art. 28, Artikel 5, Anhang III).“
    const cited = [...s.text.matchAll(/Art(?:ikel|\.)?\s*(\d+)|Anhang\s+(III)/gi)].map(m => m[1] ?? m[2]);
    // „Erlaubt sind die Artikel dieser Aufgabe, und mindestens einer muss genannt sein.“
    const ok = cited.length > 0 && cited.every(n => t.arts.includes(n.toUpperCase()));
    // „Alles erlaubt: Text übernehmen. Sonst: durch den Hinweis ersetzen und merken.“
    if (ok) summaries[t.key] = s.text.trim(); else { summaries[t.key] = NOTE; replaced.push(t.key); }
  }
}

// ---------- ABSCHNITT 4: Ergebnis ----------
// „Status: ok = alle Zusammenfassungen da, partial = einige ersetzt oder fehlend, fallback = keine KI-Antwort.“
const kiStatus = !Array.isArray(list) ? 'fallback' : (replaced.length || Object.keys(summaries).length < r.tasks.length) ? 'partial' : 'ok';
// „Aufgaben und Filter braucht die Seite nicht mehr, der Rest geht an sie.“
const { tasks, filter, ...result } = r;
// „Das Ergebnis geht an Send Result.“
return [{ json: { ...result, summaries, kiStatus, replaced } }];
